// swift-tools-version: 6.0
import PackageDescription

// Swift Package Manager support for React Native's SwiftPM autolinking
// (react-native >= 0.88). CocoaPods users are unaffected; see RNSVG.podspec.
// The two React Native packages are resolved by the autolinker relative to
// build/generated/autolinking/libs/RNSVG in the app.

// Precompiled Metal kernels that RNSVGCustomFilter loads by name; only the
// iphoneos builds ship, since this manifest is iOS only. Every kernel
// file stays excluded, even the ones copied as resources: SwiftPM reports a
// duplicate rule for a file under a sources directory that is not excluded.
let metalKernelNames = ["RNSVGArithmeticFilter", "RNSVGCompositeXor"]
let metalKernelFiles = ["metal"]
    + ["appletvos", "iphoneos", "macosx", "xros"].flatMap { sdk in ["\(sdk).air", "\(sdk).metallib"] }
let metalKernels = metalKernelNames.flatMap { kernel in
    metalKernelFiles.map { "apple/Filters/MetalCI/\(kernel).\($0)" }
}

let headerSearchPaths = [
    "common/cpp",
    // Resolves <rnsvg/...>, the subspec's header_dir in RNSVG.podspec.
    "common/cpp/react/renderer/components",
    "apple",
    "apple/Brushes",
    "apple/Elements",
    "apple/Filters",
    "apple/Filters/MetalCI",
    "apple/Shapes",
    "apple/Text",
    "apple/Utils",
]

// RCT_NEW_ARCH_ENABLED comes from install_modules_dependencies under
// CocoaPods; without it, all Fabric code compiles out. REACT_NATIVE_MINOR_VERSION
// is the app's exact minor under CocoaPods, but a static manifest cannot read
// the app's React Native version. 88 is the oldest React Native that can
// consume this manifest, so a check against any older minor holds for every
// app that can.
let defines = [
    ("RCT_NEW_ARCH_ENABLED", "1"),
    ("REACT_NATIVE_MINOR_VERSION", "88"),
]

let package = Package(
    name: "RNSVG",
    platforms: [.iOS("15.1")],
    products: [
        .library(name: "RNSVG", targets: ["RNSVG"]),
    ],
    dependencies: [
        .package(name: "ReactNative", path: "../../../../xcframeworks"),
        .package(name: "React-GeneratedCode", path: "../../../ios"),
    ],
    targets: [
        .target(
            name: "RNSVG",
            dependencies: [
                .product(name: "ReactHeaders", package: "ReactNative"),
                .product(name: "ReactNativeHeaders", package: "ReactNative"),
                .product(name: "ReactNativeDependenciesHeaders", package: "ReactNative"),
                .product(name: "ReactAppHeaders", package: "React-GeneratedCode"),
            ],
            path: ".",
            exclude: [
                "apple/RNSVG.xcodeproj",
                "apple/RNSVGUIKit.macos.mm",
                "apple/Text/RNSVGTopAlignedLabel.macos.mm",
            ] + metalKernels,
            sources: ["apple", "common/cpp"],
            resources: metalKernelNames.map {
                .copy("apple/Filters/MetalCI/\($0).iphoneos.metallib")
            },
            publicHeadersPath: "apple",
            cSettings: defines.map { .define($0, to: $1) }
                + headerSearchPaths.map { .headerSearchPath($0) },
            cxxSettings: defines.map { .define($0, to: $1) }
                + headerSearchPaths.map { .headerSearchPath($0) }
                + [
                    .define("DEBUG", .when(configuration: .debug)),
                    .define("NDEBUG", .when(configuration: .release)),
                ],
            linkerSettings: [
                .linkedFramework("UIKit"),
                .linkedFramework("Foundation"),
                .linkedFramework("CoreGraphics"),
            ]
        ),
    ],
    cxxLanguageStandard: .cxx20
)

// swift-tools-version: 6.0
//
// SwiftPM manifest for react-native-skia. iOS, Graphite.
// Additive: the CocoaPods podspec remains the supported default.
//
// React Native 0.87+ references a library that ships its own Package.swift
// through a symlink at <app>/ios/build/generated/autolinking/libs/<name>, and
// resolves the relative paths below against that symlink. They are the same
// for every standard app, because the symlink location is.

import Foundation
import PackageDescription

// Skia's xcframeworks are ~200MB and are not carried in this package. They come
// from the react-native-skia-graphite-apple-ios npm package, which
// react-native-skia depends on, so a checkout that has installed its
// dependencies builds offline. Dawn, the WebGPU implementation Graphite runs
// on, comes from the react-native-webgpu-dawn package the same way: the one
// react-native-webgpu depends on too, so an app with both links one Dawn.
// Xcode passes the symlink as the package directory, hence resolvingSymlinks.
let packageRoot = URL(fileURLWithPath: Context.packageDirectory)
  .resolvingSymlinksInPath().path

// A node package next to this one: a sibling in the consumer's node_modules,
// or under this monorepo's root.
let nodePackage = { (name: String) -> String? in
  ["../../\(name)", "../../node_modules/\(name)"]
    .map { "\(packageRoot)/\($0)" }
    .first { FileManager.default.fileExists(atPath: "\($0)/Package.swift") }
}

guard let binariesPath = nodePackage("react-native-skia-graphite-apple-ios") else {
  // Reached when the package was skipped at install time (`--omit=optional`,
  // or a non-Apple `os` filter), which SwiftPM would otherwise report as an
  // unresolvable dependency path.
  fatalError(
    """
    react-native-skia-graphite-apple-ios was not found next to react-native-skia. \
    It ships the prebuilt Skia binaries this package links against. Reinstall \
    dependencies without --omit=optional, on macOS.
    """)
}
guard let dawnPath = nodePackage("react-native-webgpu-dawn") else {
  fatalError(
    """
    react-native-webgpu-dawn was not found next to react-native-skia. It ships the \
    Dawn library this package links against. Reinstall dependencies.
    """)
}

let package = Package(
  name: "ReactNativeSkia",
  platforms: [.iOS(.v15)],
  products: [
    // Autolinking looks this name up verbatim; react-native.config.js pins it.
    .library(name: "ReactNativeSkia", targets: ["ReactNativeSkia"])
  ],
  dependencies: [
    .package(name: "React-GeneratedCode", path: "../../../ios"),
    .package(name: "ReactNative", path: "../../../../xcframeworks"),
    .package(path: binariesPath),
    .package(path: dawnPath),
  ],
  targets: [
    .target(
      name: "ReactNativeSkia",
      dependencies: [
        .product(name: "ReactHeaders", package: "ReactNative"),
        .product(name: "ReactNativeHeaders", package: "ReactNative"),
        .product(name: "ReactNativeDependenciesHeaders", package: "ReactNative"),
        .product(name: "ReactAppHeaders", package: "React-GeneratedCode"),
        .product(
          name: "react-native-skia-graphite-apple-ios",
          package: "react-native-skia-graphite-apple-ios"),
        .product(name: "react-native-webgpu-dawn", package: "react-native-webgpu-dawn"),
      ],
      // apple/ and cpp/ have no common ancestor below the package root, and
      // .headerSearchPath cannot escape the target path.
      path: ".",
      // Explicit, so SwiftPM never walks node_modules, lib, android, or the
      // headers-only cpp/skia — which carries x86 AVX skcms sources that
      // cannot build for arm64.
      sources: [
        "apple",
        "cpp/api",
        "cpp/jsi",
        "cpp/rnskia",
        "cpp/utils",
        // libskottie.a needs skjson and Apple builds no libskjson archive.
        // CocoaPods compiles this via its cpp/**/*.cpp glob.
        "cpp/skia/modules/jsonreader/SkJSONReader.cpp",
      ],
      cxxSettings: [
        // Replaces the podspec's recursive cpp/** glob, which expands to 90.
        .headerSearchPath("cpp"), // "api/…", "jsi/…", "utils/…"
        .headerSearchPath("cpp/skia"), // "include/core/…", "modules/…", "src/…"
        .headerSearchPath("cpp/dawn/include"), // "webgpu/…", "dawn/…"
        .headerSearchPath("cpp/rnskia"), // apple/ uses bare "RNSkView.h"
        .headerSearchPath("cpp/utils"), // apple/ uses bare "RNSkLog.h"

        // CocoaPods defines both project-wide for a New Architecture app; the
        // SwiftPM path defines neither. Skia's own sources no longer gate on
        // them, but React's headers do (RCT_REMOVE_LEGACY_ARCH hides the
        // legacy bridge API), so mirror what CocoaPods does.
        .define("RCT_NEW_ARCH_ENABLED", to: "1"),
        .define("RCT_REMOVE_LEGACY_ARCH", to: "1"),

        // Skia's public headers only declare the Graphite API with SK_GRAPHITE.
        .define("SK_GRAPHITE", to: "1"),
        .define("SK_IMAGE_READ_PIXELS_DISABLE_LEGACY_API", to: "1"),
        .define("SK_DISABLE_LEGACY_SHAPER_FACTORY", to: "1"),
        // The Skia binaries are release builds: their inline code is compiled
        // the same way here in every configuration (SK_RELEASE), else a Debug
        // build mixes the SK_DEBUG assertions compiled into the package with
        // the release code of the library on the same objects (a ref-counted
        // object destroyed by the library then fails the debug destructor's
        // assertion). Set explicitly: Skia would otherwise derive it from
        // NDEBUG, which the debug configuration leaves out.
        .define("SK_RELEASE", to: "1"),

        // React's prebuilt C++ ABI is NDEBUG-gated. Omitting either breaks
        // the Release link.
        .define("DEBUG", .when(configuration: .debug)),
        .define("NDEBUG", .when(configuration: .release)),
      ],
      linkerSettings: [
        .linkedFramework("MetalKit"),
        .linkedFramework("AVFoundation"),
        .linkedFramework("AVKit"),
        .linkedFramework("CoreMedia"),
      ]
    )
  ],
  // React Native's headers need C++20, and so does Skia m152: SkMathPriv.h
  // calls std::countl_zero, std::countr_zero and std::popcount.
  cxxLanguageStandard: .cxx20
)

